#[cfg(feature = "sanitize")]
impl<'a> Sanitize<'a> for MarkArray<'a> {
    const TYPE_NAME: &'static str = "MarkArray";
    fn sanitize_in(&self, ctx: &mut SanitizeContext) {
        if !ctx.enter_table("MarkArray", self.data) {
            return;
        }
        if self.mark_records_byte_range().end > self.data.len() {
            ctx.check_extent("mark_count", self.mark_count_byte_range(), self.data);
            ctx.check_extent("mark_records", self.mark_records_byte_range(), self.data);
        }
        ctx.enter_field("mark_records");
        {
            let items = self.mark_records();
            let budget = ctx.element_budget(items.len());
            for (i, item) in items.iter().enumerate().take(budget) {
                if ctx.is_done() {
                    break;
                }
                ctx.enter_index(i);
                item.sanitize_in(ctx);
                ctx.exit_index();
            }
        }
        ctx.exit_field();
        ctx.exit_table();
    }
}

